<?php
defined('ABSPATH')||exit; class CFP_Analytics{public function metric(int $funnel,string $event):int{global $wpdb; return (int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM ".CFP_Database::table('analytics')." WHERE funnel_id=%d AND event_type=%s",$funnel,$event));} public function revenue(int $funnel,string $event):float{global $wpdb; return (float)$wpdb->get_var($wpdb->prepare("SELECT SUM(value) FROM ".CFP_Database::table('analytics')." WHERE funnel_id=%d AND event_type=%s",$funnel,$event));} public function steps_count(int $funnel):int{global $wpdb; return (int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM ".CFP_Database::table('steps')." WHERE funnel_id=%d",$funnel));}}
